package am.ik.yavi.fn;

import org.jspecify.annotations.Nullable;

/**
 * A function that takes 2 arguments and produces a result.
 *
 * <p>
 * This is the 2-argument variant of {@link java.util.function.Function}, used to apply a
 * function to the values of combined validation results. Every argument is annotated
 * {@link org.jspecify.annotations.Nullable}, so implementations must accept {@code null}
 * arguments.
 *
 * <p>
 * Generated by <a href=
 * "https://github.com/making/yavi/blob/develop/scripts/generate-function.sh">generate-function.sh</a>.
 *
 * @param <T1> the type of argument 1
 * @param <T2> the type of argument 2
 * @param <R> the type of the result
 * @since 0.6.0
 */
@FunctionalInterface
public interface Function2<T1, T2, R> {

	/**
	 * Applies this function to the given arguments.
	 * @param t1 argument 1, possibly {@code null}
	 * @param t2 argument 2, possibly {@code null}
	 * @return the function result
	 */
	R apply(@Nullable T1 t1, @Nullable T2 t2);

}
